(903960, 103676, 14255, '<td valign="top">It looks as if you have a torch light shining out of the head of the flower. Nice shot.</td>', 'It looks as if you have a torch light shining out of the head of the flower. Nice shot.', '2004-09-10 20:20:54.000000', NULL, 1),
(903966, 102698, 26695, '<td valign="top">This picture feels pure and clean to me. I like that the crystals sparkle and that the light seems to be coming from the bowl itself. Love the name!</td>', 'This picture feels pure and clean to me. I like that the crystals sparkle and that the light seems to be coming from the bowl itself. Love the name!', '2004-09-10 20:27:18.000000', NULL, 1),
