INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(905852, 103590, 16046, '<td valign="top">Very cool, reminds me of  an oil rig on the ocean.</td>', 'Very cool, reminds me of  an oil rig on the ocean.', '2004-09-12 14:06:14.000000', NULL, 1),
(905853, 102177, 16829, '<td valign="top">Very fine. I like the way you''ve kept detail in her face with the backlit glow behind her. If the figure in the background was moved more to the right, the composition would be improved.</td>', 'Very fine. I like the way you''ve kept detail in her face with the backlit glow behind her. If the figure in the background was moved more to the right, the composition would be improved.', '2004-09-12 14:07:26.000000', NULL, 1),
(905854, 102357, 16046, '<td valign="top">very aristic image, great table, looks more side lit than back lit, still a nice photo</td>', 'very aristic image, great table, looks more side lit than back lit, still a nice photo', '2004-09-12 14:08:04.000000', NULL, 1),
(905856, 103985, 16046, '<td valign="top">good idea, nice work</td>', 'good idea, nice work', '2004-09-12 14:09:27.000000', NULL, 1),
(905857, 103981, 16046, '<td valign="top">Nice image, love the BG</td>', 'Nice image, love the BG', '2004-09-12 14:10:15.000000', NULL, 1),
