(907226, 103991, 25486, '<td valign="top">A pleasant picture postcard type shot.</td>', 'A pleasant picture postcard type shot.', '2004-09-13 07:06:02.000000', NULL, 1),
(907228, 102989, 25486, '<td valign="top">Exsposure is the key to any backlit shot and I''m not sure the exsposure is spot on here.  For me personally, it should have more to show more detail inside or less to lose all the inside detail altogether.</td>', 'Exsposure is the key to any backlit shot and I''m not sure the exsposure is spot on here.  For me personally, it should have more to show more detail inside or less to lose all the inside detail altogether.', '2004-09-13 07:08:33.000000', NULL, 1),
